package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;import org.w3c.dom.*;
/** Baseline only. Native confirmation state must be observed before production changes. */
final class GeometryConfirmationChecks {
 final MapAndroidChecks m;final VertexRotationChecks p;final ManagerVisualChecks v;final ManagerRotationChecks r;
 final String main="20.5 10.5 30.5\n21.5 11.5 31.5\n22.5 12.5 32.5";
 GeometryConfirmationChecks(MapAndroidChecks m){this.m=m;p=new VertexRotationChecks(m);v=p.v;r=p.r;}
 Element child(Element parent,String name){Element e=parent.getOwnerDocument().createElementNS(parent.getNamespaceURI(),name);parent.appendChild(e);return e;}
 void ring(Element polygon,String kind,String coordinates){child(child(child(polygon,kind),"LinearRing"),"coordinates").setTextContent(coordinates);}
 long fixture(Object store,boolean hole)throws Exception{long id=p.fixture.insert(store);Object d=r.load(store,id);Element feature=m.element(d,"point"),point=(Element)feature.getElementsByTagNameNS("*","Point").item(0);feature.removeChild(point);if(hole){Element polygon=child(feature,"Polygon");ring(polygon,"outerBoundaryIs","0,0,1 5,0,2 5,5,3 0,0,1");ring(polygon,"innerBoundaryIs","1,1,11 2,1,12 2,2,13 1,1,11");ring(polygon,"innerBoundaryIs","3,1,21 4,1,22 4,2,23 3,1,21");}else child(child(feature,"LineString"),"coordinates").setTextContent("10,20,30 11,21,31 12,22,32");m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,d);return id;}
 String key()throws Exception{List parts=(List)m.editorField("parts");Object part=parts.get((Integer)m.editorField("current"));return (String)part.getClass().getField("key").get(part);}
 String message(boolean hole){return hole?"Удалить только выбранный внутренний контур? Остальная область сохраняется.":"Удалить вершину 2 из текущего ввода?";}
 String positive(boolean hole){return hole?"Удалить контур":"Удалить";}
 boolean contains(View n,String value){if(n instanceof TextView&&((TextView)n).getText().toString().startsWith(value))return true;if(n instanceof ViewGroup){ViewGroup g=(ViewGroup)n;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),value))return true;}return false;}
 boolean present(boolean hole){final boolean[] result={false};m.runOnMainSync(()->{View root=m.activeDialogRoot();result[0]=contains(root,message(hole))&&v.button(root,positive(hole))!=null&&v.button(root,"Отмена")!=null;});return result[0];}
 void open(long id,boolean hole)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));p.rotate(UiAutomation.ROTATION_FREEZE_0);if(hole){m.clickDescription("Выбор геометрии и контура");m.click("Геометрия 0 · внутренний контур 2");m.geometryReady();}else m.inputs(main);m.check(key().equals(hole?"0/inner/1":"0"),"baseline selects exact intended geometry address");}
 void confirm(boolean hole)throws Exception{m.click("Действия");if(hole)m.click("Удалить внутренний контур");else{m.click("Редактировать вершины");m.click("2. 21.5 11.5 31.5");m.click("Удалить вершину");}m.check(present(hole),"native deletion confirmation fixture");}
 void snapshot(boolean hole,String stage)throws Exception{JSONObject o=new JSONObject();o.put("kind",hole?"hole":"vertex");o.put("stage",stage);o.put("present",present(hole));o.put("key",key());o.put("token",m.editorField("expected"));o.put("main",m.geometryInput());o.put("project",m.editorField("project"));o.put("feature",m.editorField("featureId"));final JSONArray texts=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),texts);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",texts);for(int i=0;i<texts.length();i++){JSONObject t=texts.getJSONObject(i);if(t.getBoolean("visible"))m.check(t.getBoolean("arimo"),"Arimo on deletion form "+t.getString("text"));}m.capture("mvisual-geometry-delete-"+(hole?"hole":"vertex")+"-"+stage);v.emit("GEOMETRY_DELETE_VISUAL "+o.toString());}
 boolean baseline(Object store,boolean hole)throws Exception{long id=fixture(store,hole);try{Object d=r.load(store,id);byte[] xml=r.xml(d);Map<String,byte[]> assets=new HashMap<>(m.assets(d));open(id,hole);String input=m.geometryInput(),address=key(),token=(String)m.editorField("expected");confirm(hole);m.click("Отмена");m.check(input.equals(m.geometryInput())&&Arrays.equals(xml,r.xml(r.load(store,id))),"Cancel native deletion never modifies main or KML");r.sameAssets(r.load(store,id),assets);confirm(hole);snapshot(hole,"before");Activity old=m.activity;p.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"deletion confirmation Activity actually destroyed and replaced");snapshot(hole,"after");boolean restored=present(hole);m.check(input.equals(m.geometryInput())&&address.equals(key())&&token.equals(m.editorField("expected")),"own main/selected part/token remain exact during baseline recreate");m.check(Arrays.equals(xml,r.xml(r.load(store,id))),"rotation never deletes or saves KML");r.sameAssets(r.load(store,id),assets);v.emit("GEOMETRY_DELETE_BASELINE kind="+(hole?"hole":"vertex")+" restored="+restored+" main/token/address/KML/assets unchanged=true");if(restored){String hash=stamp(false);identity(id,hole,token,hash,false);rotate(UiAutomation.ROTATION_FREEZE_0);identity(id,hole,token,hash,false);m.check(present(hole),"confirmation also survives actual reverse recreation");snapshot(hole,"cancel-return");m.click("Отмена");m.check(input.equals(m.geometryInput()),"Cancel after both rotations keeps exact original main");unchanged(store,id,xml,assets);ghost();unchanged(store,id,xml,assets);}return restored;}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 Object active(boolean staged)throws Exception{return m.editorField(staged?"stagedHoleDeletion":"geometryConfirmation");}
 String stamp(boolean staged)throws Exception{Object d=active(staged);return (String)d.getClass().getField("mainStamp").get(d);}
 void identity(long id,boolean hole,String token,String stamp,boolean staged)throws Exception{Object d=active(staged);m.check(d!=null,"original geometry deletion intent present");Class<?> c=d.getClass();m.check(c.getField("project").getLong(d)==id&&"point".equals(c.getField("feature").get(d))&&m.editorField("VERTEX_SESSION").equals(c.getField("session").get(d)),"original project/feature/process deletion owner retained");m.check((hole?"0/inner/1":"0").equals(c.getField("key").get(d))&&token.equals(c.getField("token").get(d))&&stamp.equals(c.getField("mainStamp").get(d))&&(hole?"hole":"vertex").equals(c.getField("kind").get(d))&&c.getField("index").getInt(d)==(hole?-1:1)&&!c.getField("addingHole").getBoolean(d),"original deletion key/token/main-stamp/kind/index retained without rebinding");}
 boolean enabled(boolean hole){final boolean[] yes={false};m.runOnMainSync(()->{View b=v.button(m.activeDialogRoot(),positive(hole));yes[0]=b!=null&&b.isEnabled();});return yes[0];}
 void changed(Object store,long id,boolean hole)throws Exception{Object doc=r.load(store,id);Element feature=m.element(doc,"point"),coordinates;if(hole){Element inner=(Element)feature.getElementsByTagNameNS("*","innerBoundaryIs").item(1);coordinates=(Element)inner.getElementsByTagNameNS("*","coordinates").item(0);coordinates.setTextContent("3,1,31 4,1,32 4,2,33 3,1,31");}else{coordinates=(Element)feature.getElementsByTagNameNS("*","coordinates").item(0);coordinates.setTextContent("14,24,34 15,25,35 16,26,36");}m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);}
 void rotate(int direction)throws Exception{Activity old=m.activity;p.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"geometry confirmation really destroyed/recreated Activity");}
 void ghost()throws Exception{m.check(active(false)==null&&active(true)==null,"completed/cancelled deletion intents cleared synchronously");rotate(m.activity.getResources().getConfiguration().orientation==1?UiAutomation.ROTATION_FREEZE_90:UiAutomation.ROTATION_FREEZE_0);m.check(active(false)==null&&active(true)==null,"no deletion intent automatically reopens or commits");}
 void unchanged(Object store,long id,byte[] expected,Map<String,byte[]> assets)throws Exception{m.check(Arrays.equals(expected,r.xml(r.load(store,id))),"KML exactly unchanged without explicit Save");r.sameAssets(r.load(store,id),assets);}
 void scenario(Object store,boolean hole,String outcome)throws Exception{long id=fixture(store,hole);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id,hole);String original=m.geometryInput(),token=(String)m.editorField("expected");confirm(hole);String hash=stamp(false);identity(id,hole,token,hash,false);if(outcome.equals("stale-before"))changed(store,id,hole);byte[] current=r.xml(r.load(store,id));rotate(UiAutomation.ROTATION_FREEZE_90);m.check(present(hole),"original deletion confirmation restored without applying");identity(id,hole,token,hash,false);unchanged(store,id,current,assets);
  if(outcome.equals("save")){m.check(enabled(hole),"unchanged deletion needs explicit enabled confirmation");snapshot(hole,"confirm");m.click(positive(hole));m.geometryReady();m.check(active(false)==null&&!present(hole),"explicit confirmation consumed once");if(hole){identity(id,true,token,hash,true);m.check(m.geometryInput().equals(original),"hole confirmation stages intent without changing raw coordinates");rotate(UiAutomation.ROTATION_FREEZE_0);identity(id,true,token,hash,true);m.check(!present(hole),"staged hole intent stays staged on recreation");}else m.check(m.geometryInput().equals("20.5 10.5 30.5\n22.5 12.5 32.5"),"confirmation deletes only middle vertex in main UI draft");unchanged(store,id,xml,assets);snapshot(hole,"before-save");m.click("Сохранить");m.geometryReady();Object actual=r.load(store,id),expected=r.parse(xml);Element feature=m.element(expected,"point");if(hole){Node chosen=feature.getElementsByTagNameNS("*","innerBoundaryIs").item(1);chosen.getParentNode().removeChild(chosen);}else ((Element)feature.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent("10.5,20.5,30.5 12.5,22.5,32.5");m.check(m.treeToken(expected).equals(m.treeToken(actual)),"explicit Save modifies only the chosen middle vertex/second inner ring, preserving all other XML");r.sameAssets(actual,assets);snapshot(hole,"saved");ghost();}
  else{if(outcome.equals("stale-after"))changed(store,id,hole);String main=m.geometryInput();if(outcome.equals("main-changed")){main=main+"\n3 3 90";final String newer=main;final EditText input=(EditText)m.editorField("input");m.runOnMainSync(()->input.setText(newer));}byte[] newest=r.xml(r.load(store,id));if(!outcome.equals("stale-before")){m.click(positive(hole));m.geometryReady();}m.check(!enabled(hole)&&present(hole),"stale geometry/main input is rejected with Cancel retained");identity(id,hole,token,hash,false);m.check(m.geometryInput().equals(main),"blocked intent never overwrites newer main input");unchanged(store,id,newest,assets);snapshot(hole,outcome);rotate(UiAutomation.ROTATION_FREEZE_0);identity(id,hole,token,hash,false);String reverseMain=hole&&outcome.equals("stale-after")?"1 3 31\n1 4 32\n2 4 33\n1 3 31":main;m.check(!enabled(hole)&&m.geometryInput().equals(reverseMain),"reverse recreation keeps newer dirty input or refreshes clean hole view without rebinding old intent");m.click("Отмена");unchanged(store,id,newest,assets);m.check(m.geometryInput().equals(reverseMain),"Cancel after rejection retains current main");ghost();}
  v.emit("GEOMETRY_DELETE_RESULT kind="+(hole?"hole":"vertex")+" outcome="+outcome+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void staleSave(Object store,boolean hole)throws Exception{long id=fixture(store,hole);try{Object doc=r.load(store,id);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id,hole);confirm(hole);rotate(UiAutomation.ROTATION_FREEZE_90);m.click(positive(hole));m.geometryReady();String main=m.geometryInput();changed(store,id,hole);byte[] newer=r.xml(r.load(store,id));m.click("Сохранить");m.geometryReady();m.waitText("Не удалось сохранить");unchanged(store,id,newer,assets);m.check(m.geometryInput().equals(main),"rejected Save preserves local input and newer KML");snapshot(hole,"stale-save");if(hole){rotate(UiAutomation.ROTATION_FREEZE_0);m.check(active(true)!=null,"stale staged hole deletion retained only as blocked intent");m.click("Действия");m.click("Отменить удаление контура");unchanged(store,id,newer,assets);ghost();}v.emit("GEOMETRY_DELETE_STALE_SAVE kind="+(hole?"hole":"vertex")+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void cancelStage(Object store)throws Exception{long id=fixture(store,true);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id,true);String main=m.geometryInput(),token=(String)m.editorField("expected");confirm(true);String hash=stamp(false);m.click(positive(true));m.geometryReady();identity(id,true,token,hash,true);rotate(UiAutomation.ROTATION_FREEZE_90);identity(id,true,token,hash,true);unchanged(store,id,xml,assets);snapshot(true,"staged-cancel");m.click("Действия");m.click("Отменить удаление контура");m.check(m.geometryInput().equals(main),"Cancel staged hole deletion retains original coordinate input");unchanged(store,id,xml,assets);snapshot(true,"cancelled-stage");ghost();v.emit("GEOMETRY_DELETE_STAGE_CANCEL PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,boolean hole,boolean project)throws Exception{long id=fixture(store,hole),other=-1;try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));long target=id;if(project){Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_GEOMETRY_FOREIGN");target=other;}open(id,hole);confirm(hole);final long pid=target;final String feature=project?"point":"other";m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",pid).putExtra("feature",feature)));rotate(UiAutomation.ROTATION_FREEZE_90);m.check((Long)m.editorField("project")==target&&feature.equals(m.editorField("featureId"))&&active(false)==null&&active(true)==null&&!present(hole),"foreign project/feature never adopts deletion intent");m.check(key().equals(project&&hole?"0/outer":"0"),"foreign owner keeps its own initial selected geometry address");m.check(m.geometryInput().equals(!project?"22 12 32":hole?"0 0 1\n0 5 2\n5 5 3\n0 0 1":"20 10 30\n21 11 31\n22 12 32"),"foreign owner keeps its own raw geometry instead of old selected contour/draft");unchanged(store,id,xml,assets);unchanged(store,target,xml,assets);snapshot(hole,project?"foreign-project":"foreign-feature");v.emit("GEOMETRY_DELETE_FOREIGN kind="+(hole?"hole":"vertex")+" project="+project+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}

 void stageMainChanged(Object store)throws Exception{long id=fixture(store,true);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id,true);String original=m.geometryInput();confirm(true);m.click(positive(true));m.geometryReady();String newer=original+"\n3 3 90";final EditText input=(EditText)m.editorField("input");m.runOnMainSync(()->input.setText(newer));m.click("Сохранить");m.geometryReady();m.check(active(true)!=null&&m.geometryInput().equals(newer),"staged Save refuses to overwrite changed main input");unchanged(store,id,xml,assets);snapshot(true,"stage-main-changed");rotate(UiAutomation.ROTATION_FREEZE_90);m.check(m.geometryInput().equals(newer)&&active(true)!=null,"changed main and blocked pending deletion survive recreation");m.click("Действия");m.click("Отменить удаление контура");m.check(m.geometryInput().equals(newer),"Cancel pending hole deletion never resets newer main");ghost();m.check(m.geometryInput().equals(newer),"newer raw main remains after cancelled staged intent and another recreation");unchanged(store,id,xml,assets);v.emit("GEOMETRY_DELETE_STAGE_MAIN_CHANGED PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void stageForeign(Object store)throws Exception{long id=fixture(store,true),other=-1;try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_HOLE_STAGE_FOREIGN");open(id,true);confirm(true);m.click(positive(true));m.geometryReady();m.check(active(true)!=null,"own hole intent explicitly staged");unchanged(store,id,xml,assets);final long target=other;m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",target)));rotate(UiAutomation.ROTATION_FREEZE_90);m.check((Long)m.editorField("project")==other&&active(true)==null&&active(false)==null&&key().equals("0/outer"),"foreign owner drops staged deletion and old selected inner contour");unchanged(store,id,xml,assets);unchanged(store,other,xml,assets);snapshot(true,"stage-foreign");v.emit("GEOMETRY_DELETE_STAGE_FOREIGN PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}

 void run(boolean hole)throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{boolean restored=baseline(store,hole);m.check(m.requests.get()==requests,"deletion baseline is local only");m.check(restored,"open deletion confirmation survives actual recreation");for(String outcome:new String[]{"save","stale-before","stale-after","main-changed"})scenario(store,hole,outcome);staleSave(store,hole);foreign(store,hole,true);foreign(store,hole,false);if(hole){cancelStage(store);stageMainChanged(store);stageForeign(store);}m.check(m.requests.get()==requests,"all deletion confirmation/staged Save operations stay local");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
